children:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&family=Source+Serif+4:opsz,wght@8..60,500;8..60,600&display=swap');

#kbc-chartered-pathway-2026 {
  --kbc-dark: #201432;
  --kbc-deep: #2b1b43;
  --kbc-medium: #3d285d;
  --kbc-muted-purple: #573a7d;
  --kbc-purple: #5c259c;
  --kbc-bright-purple: #7540dc;
  --kbc-light-purple: #f1eafa;
  --kbc-section: #f7f5fa;
  --kbc-gold: #e5bd59;
  --kbc-soft-gold: #f5e8bf;
  --kbc-text: #292f3d;
  --kbc-muted: #626a7a;
  --kbc-white: #ffffff;
  --kbc-border: rgba(87, 58, 125, 0.13);
  --kbc-border-strong: rgba(87, 58, 125, 0.22);
  --kbc-shadow: 0 8px 24px rgba(32, 20, 50, 0.055);
  --kbc-shadow-strong: 0 18px 46px rgba(32, 20, 50, 0.13);
  --kbc-radius: 18px;
  --kbc-radius-small: 12px;
  /* Fallback only. JavaScript replaces this with the measured visible header bottom. */
  --kbc-site-header-height: 52px;
  --kbc-page-nav-height: 58px;
  --kbc-admin-bar-height: 0px;
  /* Removes the extra blank strip included in some Elementor header wrappers. */
  --kbc-header-gap-correction: 0px;
  /* Final measured viewport offset. Do not add the admin bar a second time. */
  --kbc-total-sticky-offset: 52px;
  width: 100%;
  max-width: 100%;
  margin: 0;
  color: var(--kbc-text);
  background: var(--kbc-white);
  font-family: Inter, Arial, Helvetica, sans-serif;
  font-size: 16px;
  line-height: 1.65;
  overflow-x: clip;
  overflow-y: visible;
  scroll-behavior: smooth;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

#kbc-chartered-pathway-2026,
#kbc-chartered-pathway-2026 *,
#kbc-chartered-pathway-2026 *::before,
#kbc-chartered-pathway-2026 *::after {
  box-sizing: border-box;
}

#kbc-chartered-pathway-2026 h1,
#kbc-chartered-pathway-2026 h2,
#kbc-chartered-pathway-2026 h3,
#kbc-chartered-pathway-2026 h4,
#kbc-chartered-pathway-2026 p,
#kbc-chartered-pathway-2026 ul,
#kbc-chartered-pathway-2026 ol {
  margin-top: 0;
}

#kbc-chartered-pathway-2026 h1,
#kbc-chartered-pathway-2026 h2 {
  color: var(--kbc-dark);
  font-weight: 800;
  letter-spacing: -0.04em;
}

#kbc-chartered-pathway-2026 h3,
#kbc-chartered-pathway-2026 h4 {
  color: var(--kbc-dark);
  font-weight: 700;
  line-height: 1.2;
}

#kbc-chartered-pathway-2026 p,
#kbc-chartered-pathway-2026 li,
#kbc-chartered-pathway-2026 a,
#kbc-chartered-pathway-2026 button,
#kbc-chartered-pathway-2026 input,
#kbc-chartered-pathway-2026 select,
#kbc-chartered-pathway-2026 textarea {
  font-family: Inter, Arial, Helvetica, sans-serif;
}

#kbc-chartered-pathway-2026 a {
  color: inherit;
}

#kbc-chartered-pathway-2026 .kbc-skip-link {
  position: fixed;
  top: 12px;
  left: 12px;
  z-index: 9999;
  transform: translateY(-160%);
  min-height: 44px;
  padding: 10px 14px;
  border: 1px solid var(--kbc-border);
  border-radius: 10px;
  color: var(--kbc-dark);
  background: var(--kbc-white);
  box-shadow: var(--kbc-shadow-strong);
  font-weight: 800;
  text-decoration: none;
  transition: transform 180ms ease;
}

#kbc-chartered-pathway-2026 .kbc-skip-link:focus {
  transform: translateY(0);
}

#kbc-chartered-pathway-2026 .kbc-container {
  width: min(1220px, calc(100% - 40px));
  margin-inline: auto;
}

#kbc-chartered-pathway-2026 .kbc-section {
  position: relative;
  padding: 72px 0;
  scroll-margin-top: calc(var(--kbc-total-sticky-offset) + var(--kbc-page-nav-height) + 20px);
}

#kbc-chartered-pathway-2026 main > .kbc-section:nth-of-type(odd) {
  background: var(--kbc-white);
}

#kbc-chartered-pathway-2026 main > .kbc-section:nth-of-type(even) {
  background: var(--kbc-section);
}

#kbc-chartered-pathway-2026 .kbc-section-head {
  max-width: 900px;
  margin-bottom: 34px;
}

#kbc-chartered-pathway-2026 .kbc-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  margin-bottom: 14px;
  color: var(--kbc-muted-purple);
  font-size: 13px;
  font-weight: 800;
  line-height: 1.35;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

#kbc-chartered-pathway-2026 .kbc-eyebrow::before {
  content: "";
  width: 38px;
  height: 5px;
  flex: 0 0 auto;
  border-radius: 999px;
  background: var(--kbc-gold);
}

#kbc-chartered-pathway-2026 .kbc-section-title {
  margin-bottom: 16px;
  font-size: clamp(1.7rem, 3vw, 2.6rem);
  line-height: 1.08;
}

#kbc-chartered-pathway-2026 .kbc-lead {
  max-width: 850px;
  margin-bottom: 0;
  color: var(--kbc-muted);
  font-size: clamp(1rem, 1.35vw, 1.15rem);
  line-height: 1.7;
}

#kbc-chartered-pathway-2026 .kbc-hero {
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  min-height: 690px;
  padding: 84px 0;
  overflow: hidden;
  color: var(--kbc-white);
  background:
    radial-gradient(circle at 84% 18%, rgba(229, 189, 89, 0.11), transparent 28%),
    radial-gradient(circle at 8% 82%, rgba(117, 64, 220, 0.18), transparent 34%),
    linear-gradient(135deg, #1b102d, #302048, #201432);
}

#kbc-chartered-pathway-2026 .kbc-hero::before,
#kbc-chartered-pathway-2026 .kbc-hero::after {
  content: "";
  position: absolute;
  z-index: -1;
  border-radius: 50%;
  pointer-events: none;
}

#kbc-chartered-pathway-2026 .kbc-hero::before {
  top: -210px;
  right: -160px;
  width: 520px;
  height: 520px;
  border: 1px solid rgba(255, 255, 255, 0.075);
}

#kbc-chartered-pathway-2026 .kbc-hero::after {
  right: 6%;
  bottom: -290px;
  width: 580px;
  height: 580px;
  border: 1px solid rgba(229, 189, 89, 0.13);
}

#kbc-chartered-pathway-2026 .kbc-hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.18fr) minmax(330px, 0.82fr);
  gap: clamp(36px, 5vw, 70px);
  align-items: center;
}

#kbc-chartered-pathway-2026 .kbc-brand {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 50px;
  color: var(--kbc-white);
  font-size: 18px;
  font-weight: 800;
  line-height: 1.12;
}

#kbc-chartered-pathway-2026 .kbc-brand-mark {
  display: inline-grid;
  place-items: center;
  width: 44px;
  height: 44px;
  flex: 0 0 auto;
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 12px;
  color: var(--kbc-dark);
  background: var(--kbc-gold);
  box-shadow: 0 10px 24px rgba(229, 189, 89, 0.18);
  font-weight: 900;
}

#kbc-chartered-pathway-2026 .kbc-hero .kbc-eyebrow {
  color: var(--kbc-gold);
}

#kbc-chartered-pathway-2026 .kbc-hero .kbc-eyebrow::before {
  display: none;
}

#kbc-chartered-pathway-2026 .kbc-hero h1 {
  max-width: 780px;
  margin-bottom: 24px;
  color: var(--kbc-white);
  font-size: clamp(2.5rem, 5vw, 4.4rem);
  line-height: 1;
  letter-spacing: -0.05em;
}

#kbc-chartered-pathway-2026 .kbc-hero-description {
  max-width: 760px;
  margin-bottom: 26px;
  color: rgba(255, 255, 255, 0.84);
  font-size: clamp(1rem, 1.55vw, 1.22rem);
  line-height: 1.65;
}

#kbc-chartered-pathway-2026 .kbc-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin: 0 0 28px;
}

#kbc-chartered-pathway-2026 .kbc-badge {
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  padding: 7px 14px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 999px;
  color: var(--kbc-white);
  background: rgba(255, 255, 255, 0.075);
  font-size: 13px;
  font-weight: 700;
  backdrop-filter: blur(5px);
}

#kbc-chartered-pathway-2026 .kbc-hero-footnote {
  max-width: 780px;
  margin-bottom: 0;
  color: rgba(255, 255, 255, 0.68);
  font-size: 14px;
  line-height: 1.65;
}

#kbc-chartered-pathway-2026 .kbc-hero-side {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 410px;
  padding: 34px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 24px;
  background: rgba(86, 54, 119, 0.27);
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.15);
  backdrop-filter: blur(8px);
}

#kbc-chartered-pathway-2026 .kbc-hero-side::before {
  content: "";
  position: absolute;
  inset: 18px;
  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 18px;
  pointer-events: none;
}

#kbc-chartered-pathway-2026 .kbc-hero-orbit {
  position: relative;
  display: grid;
  place-items: center;
  width: min(292px, 88%);
  aspect-ratio: 1;
  border: 1px solid rgba(229, 189, 89, 0.62);
  border-radius: 50%;
  color: var(--kbc-white);
  background: radial-gradient(circle, rgba(255, 255, 255, 0.04), transparent 66%);
  font-size: clamp(3rem, 6vw, 4.7rem);
  font-weight: 800;
  letter-spacing: -0.06em;
  text-shadow: 0 10px 26px rgba(0, 0, 0, 0.16);
}

#kbc-chartered-pathway-2026 .kbc-hero-orbit::after {
  content: "";
  position: absolute;
  inset: 14px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: inherit;
}

#kbc-chartered-pathway-2026 .kbc-hero-year {
  position: absolute;
  right: 28px;
  bottom: 24px;
  color: var(--kbc-gold);
  font-size: 1.15rem;
  font-weight: 800;
}

#kbc-chartered-pathway-2026 .kbc-grid {
  display: grid;
  gap: 22px;
  align-items: stretch;
}

#kbc-chartered-pathway-2026 .kbc-grid-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

#kbc-chartered-pathway-2026 .kbc-grid-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

#kbc-chartered-pathway-2026 .kbc-grid-4 {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

#kbc-chartered-pathway-2026 .kbc-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  height: 100%;
  padding: 22px 24px;
  border: 1px solid var(--kbc-border);
  border-radius: var(--kbc-radius);
  background: var(--kbc-white);
  box-shadow: var(--kbc-shadow);
}

#kbc-chartered-pathway-2026 .kbc-card--soft {
  background: linear-gradient(145deg, var(--kbc-white) 0%, #faf8fd 46%, var(--kbc-light-purple) 100%);
}

#kbc-chartered-pathway-2026 .kbc-card--dark {
  color: var(--kbc-white);
  border-color: rgba(255, 255, 255, 0.11);
  background:
    radial-gradient(circle at 100% 0%, rgba(117, 64, 220, 0.22), transparent 36%),
    linear-gradient(135deg, #201432, #3d285d);
  box-shadow: 0 14px 34px rgba(32, 20, 50, 0.16);
}

#kbc-chartered-pathway-2026 .kbc-card--dark > h3,
#kbc-chartered-pathway-2026 .kbc-card--dark > h4,
#kbc-chartered-pathway-2026 .kbc-card--dark > p {
  color: var(--kbc-white);
}

#kbc-chartered-pathway-2026 .kbc-card--dark > p {
  color: rgba(255, 255, 255, 0.8);
}

#kbc-chartered-pathway-2026 .kbc-card--dark > .kbc-list > li {
  color: rgba(255, 255, 255, 0.86);
}

#kbc-chartered-pathway-2026 .kbc-card--gold-outline {
  border-color: rgba(229, 189, 89, 0.52);
  background: var(--kbc-white);
  box-shadow: inset 0 3px 0 var(--kbc-gold), var(--kbc-shadow);
}

#kbc-chartered-pathway-2026 .kbc-card h3 {
  margin-bottom: 10px;
  font-size: 1.22rem;
}

#kbc-chartered-pathway-2026 .kbc-card h4 {
  margin-bottom: 8px;
  font-size: 1.02rem;
}

#kbc-chartered-pathway-2026 .kbc-card p {
  margin-bottom: 0;
  color: var(--kbc-muted);
  font-size: 15px;
  line-height: 1.65;
}

#kbc-chartered-pathway-2026 .kbc-card > .kbc-actions,
#kbc-chartered-pathway-2026 .kbc-card > .kbc-btn {
  margin-top: auto;
}

#kbc-chartered-pathway-2026 .kbc-card--dark .kbc-card {
  border-color: rgba(87, 58, 125, 0.14);
  color: var(--kbc-text);
  background: var(--kbc-white);
  box-shadow: 0 8px 18px rgba(15, 8, 25, 0.11);
}

#kbc-chartered-pathway-2026 .kbc-card--dark .kbc-card h3,
#kbc-chartered-pathway-2026 .kbc-card--dark .kbc-card h4 {
  color: var(--kbc-dark);
}

#kbc-chartered-pathway-2026 .kbc-card--dark .kbc-card p {
  color: var(--kbc-muted);
}

#kbc-chartered-pathway-2026 .kbc-letter {
  display: inline-grid;
  place-items: center;
  width: 42px;
  height: 42px;
  margin-bottom: 18px;
  border-radius: 12px;
  color: var(--kbc-white);
  background: linear-gradient(135deg, var(--kbc-dark), var(--kbc-purple));
  box-shadow: 0 8px 18px rgba(92, 37, 156, 0.17);
  font-size: 14px;
  font-weight: 800;
}

#kbc-chartered-pathway-2026 .kbc-split {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(320px, 0.65fr);
  gap: 28px;
  align-items: stretch;
}

#kbc-chartered-pathway-2026 .kbc-stat-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 18px;
}

#kbc-chartered-pathway-2026 .kbc-stat {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 142px;
  padding: 19px;
  border: 1px solid var(--kbc-border);
  border-radius: 16px;
  background: var(--kbc-white);
  text-align: center;
}

#kbc-chartered-pathway-2026 .kbc-stat strong {
  display: block;
  margin-bottom: 7px;
  color: var(--kbc-purple);
  font-size: clamp(1.8rem, 3vw, 2.45rem);
  line-height: 1;
}

#kbc-chartered-pathway-2026 .kbc-stat span {
  color: var(--kbc-muted);
  font-size: 14px;
  line-height: 1.45;
}

#kbc-chartered-pathway-2026 .kbc-logo-box {
  display: grid;
  place-items: center;
  width: 100%;
  min-height: 122px;
  padding: 18px;
  border: 1px solid var(--kbc-border);
  border-radius: 16px;
  background: var(--kbc-white);
  text-align: center;
}

#kbc-chartered-pathway-2026 .kbc-logo-box img {
  display: block;
  width: 120px;
  height: 54px;
  object-fit: contain;
  object-position: center;
}

#kbc-chartered-pathway-2026 .kbc-logo-box strong {
  max-width: 290px;
  color: var(--kbc-dark);
  font-size: 1.05rem;
  line-height: 1.35;
}

#kbc-chartered-pathway-2026 .kbc-info {
  margin-top: 24px;
  padding: 20px 22px;
  border: 1px solid var(--kbc-border);
  border-left: 4px solid var(--kbc-purple);
  border-radius: 0 16px 16px 0;
  color: var(--kbc-muted);
  background: var(--kbc-white);
  box-shadow: var(--kbc-shadow);
  font-size: 15px;
  line-height: 1.65;
}

#kbc-chartered-pathway-2026 .kbc-info strong {
  color: var(--kbc-purple);
}

#kbc-chartered-pathway-2026 .kbc-list {
  list-style: none;
  padding: 0;
  margin-bottom: 0;
}

#kbc-chartered-pathway-2026 .kbc-list li {
  position: relative;
  padding-left: 30px;
  color: var(--kbc-muted);
  font-size: 15px;
  line-height: 1.58;
}

#kbc-chartered-pathway-2026 .kbc-list li + li {
  margin-top: 10px;
}

#kbc-chartered-pathway-2026 .kbc-list li::before {
  content: "✓";
  position: absolute;
  top: 0.12em;
  left: 0;
  display: grid;
  place-items: center;
  width: 19px;
  height: 19px;
  border-radius: 50%;
  color: var(--kbc-purple);
  background: var(--kbc-light-purple);
  font-size: 11px;
  font-weight: 900;
  line-height: 1;
}

#kbc-chartered-pathway-2026 .kbc-card--dark > .kbc-list > li::before {
  color: var(--kbc-dark);
  background: var(--kbc-gold);
}

#kbc-chartered-pathway-2026 .kbc-nav-shell {
  position: -webkit-sticky;
  position: sticky;
  top: var(--kbc-total-sticky-offset);
  margin-top: -1px;
  z-index: 1000;
  width: 100%;
  min-height: 0;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  border-bottom: 1px solid rgba(255, 255, 255, 0.10);
  color: var(--kbc-white);
  background: #17131f;
  box-shadow: 0 8px 24px rgba(32, 20, 50, 0.16);
  isolation: isolate;
}

#kbc-chartered-pathway-2026 .kbc-nav-scroll {
  overflow-x: auto;
  overflow-y: hidden;
  overscroll-behavior-inline: contain;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}

#kbc-chartered-pathway-2026 .kbc-nav-scroll::-webkit-scrollbar {
  display: none;
}

#kbc-chartered-pathway-2026 .kbc-nav {
  display: flex;
  align-items: center;
  gap: 16px;
  min-width: max-content;
  padding: 8px 0;
  white-space: nowrap;
}

#kbc-chartered-pathway-2026 .kbc-nav a {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-height: 42px;
  padding: 9px 14px;
  border: 1px solid transparent;
  border-radius: 9px;
  color: var(--kbc-white);
  background: transparent;
  font-size: 12px;
  font-weight: 750;
  line-height: 1.2;
  text-decoration: none;
  white-space: nowrap;
  transition: color 160ms ease, background-color 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
}

#kbc-chartered-pathway-2026 .kbc-nav a::after {
  content: "";
  position: absolute;
  right: 13px;
  bottom: 5px;
  left: 13px;
  height: 2px;
  border-radius: 999px;
  background: transparent;
}

#kbc-chartered-pathway-2026 .kbc-nav a:hover {
  color: var(--kbc-white);
  background: rgba(255, 255, 255, 0.08);
}

#kbc-chartered-pathway-2026 .kbc-nav a.is-active,
#kbc-chartered-pathway-2026 .kbc-nav a[aria-current="location"] {
  color: var(--kbc-white);
  border-color: rgba(229, 189, 89, 0.28);
  background: rgba(255, 255, 255, 0.12);
}

#kbc-chartered-pathway-2026 .kbc-nav a.is-active::after,
#kbc-chartered-pathway-2026 .kbc-nav a[aria-current="location"]::after {
  background: var(--kbc-gold);
}

#kbc-chartered-pathway-2026 .kbc-nav a:focus-visible {
  outline: 3px solid var(--kbc-gold);
  outline-offset: 2px;
  background: rgba(255, 255, 255, 0.10);
}

#kbc-chartered-pathway-2026 .kbc-nav-group {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  gap: 6px;
  padding-right: 18px;
  border-right: 1px solid rgba(255, 255, 255, 0.12);
}

#kbc-chartered-pathway-2026 .kbc-nav-group:last-child {
  padding-right: 0;
  border-right: 0;
}

#kbc-chartered-pathway-2026 .kbc-module-banner {
  position: relative;
  overflow: hidden;
  padding: 34px;
  margin-bottom: 28px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 22px;
  color: var(--kbc-white);
  background:
    radial-gradient(circle at 94% 10%, rgba(117, 64, 220, 0.25), transparent 33%),
    linear-gradient(135deg, #1b102d, #3d285d);
  box-shadow: 0 16px 42px rgba(32, 20, 50, 0.14);
}

#kbc-chartered-pathway-2026 .kbc-module-banner::after {
  content: "";
  position: absolute;
  top: -90px;
  right: -80px;
  width: 260px;
  height: 260px;
  border: 1px solid rgba(255, 255, 255, 0.11);
  border-radius: 50%;
  pointer-events: none;
}

#kbc-chartered-pathway-2026 .kbc-module-banner .kbc-eyebrow {
  color: var(--kbc-soft-gold);
}

