    if (currentId) {
      usedIds[currentId] = true;
      return currentId;
    }

    var base = slugify(getSectionHeading(section)) || "pathway-section-" + (index + 1);
    var candidate = base;
    var suffix = 2;

    while (usedIds[candidate] || document.getElementById(candidate)) {
      candidate = base + "-" + suffix;
      suffix += 1;
    }

    section.id = candidate;
    usedIds[candidate] = true;
    return candidate;
  }

  function getNavigationLabel(section, sectionId) {
    var knownLabels = {
      "pathway-overview": "Overview",
      "catalogue-navigation": "Pathway",
      "role-fit": "Role fit",
      "pathway-structure": "Structure",
      "occupational-standard": "Capability",
      "certified-pmo-core": "Certified PMO",
      "module-1": "Module 1",
      "module-2": "Module 2",
      "module-3": "Module 3",
      "module-4": "Module 4",
      "ai-project-controls": "AI",
      "portfolio-management": "Portfolio",
      "earned-value-management": "EVM",
      "professional-evidence": "Evidence",
      "delivery": "Delivery",
      "eligibility": "Eligibility",
      "sources-contact": "Contact"
    };

    var explicitLabel = cleanText(section.getAttribute("data-nav-label"));
    if (explicitLabel) {
