  if (!navSentinel || !navSentinel.classList.contains("kbc-nav-sentinel")) {
    navSentinel = document.createElement("div");
    navSentinel.className = "kbc-nav-sentinel";
    navSentinel.setAttribute("aria-hidden", "true");
    navShell.parentNode.insertBefore(navSentinel, navShell);
  }

  root.setAttribute("data-kbc-sticky-nav-ready", "true");

  var floatingCta = root.querySelector(".kbc-floating-cta");
  var floatingCtaTicking = false;

  function updateFloatingCtaVisibility() {
    floatingCtaTicking = false;

    if (!floatingCta) {
      return;
    }

    var shouldShow = window.scrollY > 140;
    floatingCta.classList.toggle("is-visible", shouldShow);
    floatingCta.setAttribute("aria-hidden", shouldShow ? "false" : "true");
  }

  function requestFloatingCtaUpdate() {
    if (floatingCtaTicking) {
      return;
    }

    floatingCtaTicking = true;
    window.requestAnimationFrame(updateFloatingCtaVisibility);
  }

  if (floatingCta) {
    updateFloatingCtaVisibility();
    window.addEventListener("scroll", requestFloatingCtaUpdate, { passive: true });
  }

  var reduceMotion = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var headerSelectors = [
    "header",
    "#masthead",
    ".site-header",
    ".main-header",
    ".header",
    ".elementor-location-header",
    '[data-elementor-type="header"]',
    "header.elementor",
    ".elementor-sticky",
    ".elementor-sticky--active",
    ".ast-primary-header-bar",
    ".ast-builder-grid-row-container",
    ".et-l--header",
    ".fusion-header-wrapper",
    ".fusion-header",
    ".site-header-section",
    ".header-wrapper",
    ".main-navigation",
    ".wp-site-blocks > header",
    ".wp-block-template-part > header",
    "[role=\"banner\"]",
    "body > header",
    "body > nav",
    "nav",
    "[class*=\"header\"]",
    "[id*=\"header\"]",
    ".elementor-widget-nav-menu",
    ".elementor-nav-menu--main",
    ".e-n-menu",
    ".e-n-menu-wrapper"
  ];

  var sectionPairs = navLinks.map(function (link, index) {
    var href = link.getAttribute("href");
    if (!href || href.charAt(0) !== "#") {
      return null;
    }

    var target;
    try {
      target = root.querySelector(href);
    } catch (error) {
      target = null;
    }

    return target ? { link: link, target: target, index: index } : null;
  }).filter(Boolean);

  var layoutFrame = 0;
  var resizeTimer = 0;
  var scrollTimer = 0;
  var activeObserver = null;
  var activeObserverKey = "";
  var resizeObserver = null;
  var mutationObserver = null;
  var observedHeaders = [];
  var currentActiveLink = null;
  var lastMeasuredOffset = -1;
  var lastMeasuredNavHeight = -1;

  function numberFromCustomProperty(name) {
    var value = window.getComputedStyle(root).getPropertyValue(name);
    var parsed = parseFloat(value);
    return Number.isFinite(parsed) ? parsed : 0;
  }

  function isVisible(element) {
    if (!element || element === navShell || root.contains(element)) {
      return false;
    }

    var style = window.getComputedStyle(element);
    if (
      style.display === "none" ||
      style.visibility === "hidden" ||
      parseFloat(style.opacity || "1") <= 0.01
    ) {
      return false;
    }

    var rect = element.getBoundingClientRect();
    return rect.width > 120 && rect.height > 18 && rect.bottom > 0;
  }

  function getAdminBarMetrics() {
    var adminBar = document.getElementById("wpadminbar");
    if (!adminBar || !isVisible(adminBar)) {
      return { height: 0, bottom: 0 };
    }

    var rect = adminBar.getBoundingClientRect();
    var height = Math.max(0, Math.min(rect.height, 80));
    var bottom = Math.max(0, Math.min(rect.bottom, 80));
    return { height: height, bottom: bottom };
  }

  function collectHeaderCandidates() {
    var unique = [];
    var seen = [];

    headerSelectors.forEach(function (selector) {
      var nodes;
      try {
        nodes = document.querySelectorAll(selector);
      } catch (error) {
        nodes = [];
      }

      Array.prototype.forEach.call(nodes, function (node) {
        if (seen.indexOf(node) !== -1 || !isVisible(node)) {
          return;
        }

        var rect = node.getBoundingClientRect();
        var topLimit = Math.min(280, Math.max(180, window.innerHeight * 0.32));

        if (rect.top >= topLimit || rect.bottom <= 0 || rect.height > 260) {
          return;
        }

        seen.push(node);
        unique.push(node);
      });
    });

    return unique;
  }

  function getResponsiveFallbackHeaderHeight() {
    if (window.innerWidth <= 480) {
      return 60;
    }
    if (window.innerWidth <= 1024) {
      return 58;
    }
    return 52;
  }

  function measureHeaderContentBottom(candidate) {
    if (!candidate) {
      return 0;
    }

    var candidateRect = candidate.getBoundingClientRect();
    var contentBottom = 0;
    var contentSelectors = [
      "a",
      "button",
      "img",
      "svg",
      "input",
      "[role='button']",
      ".elementor-button",
      ".custom-logo-link",
      ".site-logo",
      ".site-title",
      ".menu-item"
    ].join(",");

    var contentNodes = [];

    try {
      contentNodes = candidate.querySelectorAll(contentSelectors);
    } catch (error) {
      contentNodes = [];
    }

    Array.prototype.forEach.call(contentNodes, function (node) {
      if (!isVisible(node) || root.contains(node)) {
        return;
      }

      var rect = node.getBoundingClientRect();

      if (
        rect.width < 2 ||
        rect.height < 2 ||
        rect.bottom <= 0 ||
        rect.top > 230 ||
        rect.bottom > candidateRect.bottom + 2
      ) {
        return;
      }

      contentBottom = Math.max(contentBottom, rect.bottom);
    });

    if (!contentBottom) {
      return Math.max(0, Math.min(candidateRect.bottom, 220));
    }

    /*
     * Elementor can leave an empty transparent area at the bottom of a
     * header wrapper. Use the visible logo/menu/button edge plus a small
     * visual padding instead of the oversized wrapper edge.
     */
    if (candidateRect.bottom - contentBottom > 14) {
      return Math.max(0, Math.min(contentBottom + 8, 220));
    }

    return Math.max(0, Math.min(candidateRect.bottom, 220));
  }

  function chooseVisibleHeaderBottom(samples, adminBottom) {
    if (!samples.length) {
      return 0;
    }

    var minimumUsefulBottom = Math.max(34, adminBottom + 22);
    var values = samples
      .filter(function (value) {
        return value >= minimumUsefulBottom && value <= 220;
      })
      .sort(function (a, b) {
        return a - b;
      });

    if (!values.length) {
      values = samples.slice().sort(function (a, b) {
        return a - b;
      });
    }

    var clusters = [];

    values.forEach(function (value) {
      var matched = null;

      clusters.some(function (cluster) {
        if (Math.abs(cluster.average - value) <= 7) {
          matched = cluster;
          return true;
        }
        return false;
      });

      if (!matched) {
        matched = {
          values: [],
          average: value
        };
        clusters.push(matched);
      }

      matched.values.push(value);
      matched.average = matched.values.reduce(function (sum, item) {
        return sum + item;
      }, 0) / matched.values.length;
    });

    /*
     * Prefer the first meaningful visible edge. Large outer Elementor
     * wrappers often end lower than the actual visible website header.
     */
    clusters.sort(function (a, b) {
      return a.average - b.average;
    });

    return clusters.length ? clusters[0].average : values[0];
  }

  function measureHeaderOffset() {
    var admin = getAdminBarMetrics();
    var candidates = collectHeaderCandidates();
    var bottomSamples = [];

    candidates.forEach(function (candidate) {
      var effectiveBottom = measureHeaderContentBottom(candidate);

      if (effectiveBottom > 0) {
        bottomSamples.push(effectiveBottom);
      }
    });

    var adminContribution = Math.max(0, Math.min(admin.height, 80));
    var visibleHeaderBottom = chooseVisibleHeaderBottom(bottomSamples, admin.bottom);
    var siteHeaderHeight = 0;
    var totalOffset = 0;

    if (visibleHeaderBottom > 0) {
      /*
       * getBoundingClientRect().bottom is already a viewport position.
       * When the WordPress toolbar is visible, this value normally
       * already includes the toolbar. Therefore it is the final sticky
       * offset and the admin-bar height must not be added again.
       */
      totalOffset = Math.max(visibleHeaderBottom, adminContribution);
      siteHeaderHeight = Math.max(0, totalOffset - adminContribution);
    } else if (window.scrollY < 140) {
      siteHeaderHeight = getResponsiveFallbackHeaderHeight();
      totalOffset = siteHeaderHeight + adminContribution;
    } else {
      totalOffset = adminContribution;
    }

    siteHeaderHeight = Math.max(0, Math.min(siteHeaderHeight, 220));
    totalOffset = Math.max(0, Math.min(totalOffset, 220));

    return {
      siteHeaderHeight: siteHeaderHeight,
      adminHeight: adminContribution,
      total: totalOffset,
      candidates: candidates
    };
  }

  function measureNavigationHeight() {
    var rect = navShell.getBoundingClientRect();
    return Math.max(42, Math.min(Math.ceil(rect.height), 140));
  }

  function observeHeaderCandidates(candidates) {
    if (!resizeObserver) {
      return;
    }

    var unchanged = candidates.length === observedHeaders.length && candidates.every(function (element, index) {
      return element === observedHeaders[index];
    });

    if (unchanged) {
      return;
    }

    observedHeaders.forEach(function (element) {
      try {
        resizeObserver.unobserve(element);
      } catch (error) {
        return;
      }
    });

    observedHeaders = candidates.slice();
    observedHeaders.forEach(function (element) {
      try {
        resizeObserver.observe(element);
      } catch (error) {
        return;
      }
    });
  }

  function setActiveLink(link, allowNavScroll) {
    if (!link || currentActiveLink === link) {
      return;
    }

    navLinks.forEach(function (item) {
      var isCurrent = item === link;
      item.classList.toggle("is-active", isCurrent);
      if (isCurrent) {
        item.setAttribute("aria-current", "location");
      } else {
        item.removeAttribute("aria-current");
      }
    });

    currentActiveLink = link;

    if (allowNavScroll !== false) {
      keepActiveLinkVisible(link);
    }
  }

  function keepActiveLinkVisible(link) {
    /*
     * Desktop keeps the navigation aligned from its first link.
     * Automatic horizontal centring is reserved for tablet/mobile.
     */
    if (window.innerWidth > 1024) {
      return;
    }

    if (!link || navScroll.scrollWidth <= navScroll.clientWidth + 2) {
      return;
    }

    var linkRect = link.getBoundingClientRect();
    var scrollRect = navScroll.getBoundingClientRect();
    var inset = 18;
    var isOutsideLeft = linkRect.left < scrollRect.left + inset;
    var isOutsideRight = linkRect.right > scrollRect.right - inset;

    if (!isOutsideLeft && !isOutsideRight) {
      return;
    }

    var linkCentre = link.offsetLeft + link.offsetWidth / 2;
    var targetLeft = Math.max(0, linkCentre - navScroll.clientWidth / 2);
