      left: targetLeft,
      behavior: reduceMotion ? "auto" : "smooth"
    });
  }

  function configureActiveObserver(totalOffset, navHeight) {
    if (!("IntersectionObserver" in window)) {
      return;
    }

    var key = Math.round(totalOffset) + ":" + Math.round(navHeight) + ":" + window.innerHeight;
    if (activeObserver && activeObserverKey === key) {
      return;
    }

    if (activeObserver) {
      activeObserver.disconnect();
    }

    activeObserverKey = key;
    var adjustedTop = Math.max(0, Math.round(totalOffset + navHeight + 18));
    var bottomMargin = Math.max(45, Math.round(window.innerHeight * 0.62));
    var visibleEntries = new Map();

    activeObserver = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          visibleEntries.set(entry.target, entry);
        } else {
          visibleEntries.delete(entry.target);
        }
      });

      var candidates = sectionPairs.filter(function (pair) {
        return visibleEntries.has(pair.target);
      }).map(function (pair) {
        var rect = pair.target.getBoundingClientRect();
        var entry = visibleEntries.get(pair.target);
        return {
          pair: pair,
          distance: Math.abs(rect.top - adjustedTop),
          ratio: entry ? entry.intersectionRatio : 0
        };
      });

      if (!candidates.length) {
        updateActiveFromPosition(adjustedTop);
        return;
      }

      candidates.sort(function (a, b) {
        if (Math.abs(a.distance - b.distance) > 24) {
          return a.distance - b.distance;
        }
        if (Math.abs(a.ratio - b.ratio) > 0.04) {
          return b.ratio - a.ratio;
        }
        return a.pair.index - b.pair.index;
      });

      setActiveLink(candidates[0].pair.link, true);
    }, {
      root: null,
      rootMargin: "-" + adjustedTop + "px 0px -" + bottomMargin + "px 0px",
      threshold: [0, 0.01, 0.15, 0.35, 0.6]
    });

    sectionPairs.forEach(function (pair) {
      activeObserver.observe(pair.target);
    });
  }

  function updateActiveFromPosition(adjustedTop) {
    if (!sectionPairs.length) {
      return;
    }

    var best = sectionPairs[0];
    var bestDistance = Number.POSITIVE_INFINITY;

    sectionPairs.forEach(function (pair) {
      var rect = pair.target.getBoundingClientRect();
      var distance;

      if (rect.top <= adjustedTop && rect.bottom > adjustedTop) {
        distance = Math.abs(rect.top - adjustedTop) * 0.25;
      } else {
        distance = Math.abs(rect.top - adjustedTop);
      }

      if (distance < bestDistance) {
        bestDistance = distance;
        best = pair;
      }
    });

    setActiveLink(best.link, true);
  }

  function getCorrectedHeaderOffset(rawOffset) {
    var correction = numberFromCustomProperty("--kbc-header-gap-correction");
    return Math.max(0, rawOffset - correction - 2);
  }

  function updateStickyNavigationState(totalOffset) {
    if (!navSentinel || !navShell) {
      return;
    }

    var sentinelTop = navSentinel.getBoundingClientRect().top;
    navShell.classList.toggle("is-stuck", sentinelTop <= totalOffset + 1);
  }

  function applyMeasurements() {
    layoutFrame = 0;

    var header = measureHeaderOffset();
    var correctedHeaderOffset = getCorrectedHeaderOffset(header.total);
    var navHeight = measureNavigationHeight();

    root.style.setProperty("--kbc-site-header-height", header.siteHeaderHeight.toFixed(2) + "px");
    root.style.setProperty("--kbc-admin-bar-height", header.adminHeight.toFixed(2) + "px");
    root.style.setProperty("--kbc-total-sticky-offset", correctedHeaderOffset.toFixed(2) + "px");
    root.style.setProperty("--kbc-page-nav-height", navHeight.toFixed(2) + "px");

    observeHeaderCandidates(header.candidates);
    updateStickyNavigationState(correctedHeaderOffset);

    if (
      Math.abs(correctedHeaderOffset - lastMeasuredOffset) > 0.5 ||
      Math.abs(navHeight - lastMeasuredNavHeight) > 0.5
    ) {
      lastMeasuredOffset = correctedHeaderOffset;
      lastMeasuredNavHeight = navHeight;
      configureActiveObserver(correctedHeaderOffset, navHeight);
    }

    updateActiveFromPosition(correctedHeaderOffset + navHeight + 18);
  }

  function scheduleMeasurements() {
    if (layoutFrame) {
      return;
    }
    layoutFrame = window.requestAnimationFrame(applyMeasurements);
  }

  function getCurrentOffsets() {
    return {
      total: numberFromCustomProperty("--kbc-total-sticky-offset"),
      nav: numberFromCustomProperty("--kbc-page-nav-height")
    };
  }

  function scrollToTarget(target, updateHistory) {
    if (!target) {
      return;
    }

    scheduleMeasurements();
    var offsets = getCurrentOffsets();
    var targetTop = target.getBoundingClientRect().top + window.pageYOffset - offsets.total - offsets.nav - 20;

    window.scrollTo({
      top: Math.max(0, targetTop),
      behavior: reduceMotion ? "auto" : "smooth"
