  }

  navLinks.forEach(function (link) {
    link.addEventListener("click", function (event) {
      var href = link.getAttribute("href");
      var target;

      try {
        target = href ? root.querySelector(href) : null;
      } catch (error) {
        target = null;
      }

      if (!target) {
        return;
      }

      event.preventDefault();
      setActiveLink(link, false);
      scrollToTarget(target, true);
    });
  });

  window.addEventListener("hashchange", function () {
    var hash = window.location.hash;
    var target;

    if (!hash || hash === "#") {
      return;
    }

    try {
      target = root.querySelector(hash);
    } catch (error) {
      target = null;
    }

    if (target) {
      window.requestAnimationFrame(function () {
        scrollToTarget(target, false);
      });
    }
  });

  window.addEventListener("resize", function () {
    window.clearTimeout(resizeTimer);
    resizeTimer = window.setTimeout(function () {
      if (window.innerWidth > 1024 && navScroll) {
        navScroll.scrollLeft = 0;
      }
      scheduleMeasurements();
    }, 90);
  }, { passive: true });

  window.addEventListener("orientationchange", function () {
    window.clearTimeout(resizeTimer);
    resizeTimer = window.setTimeout(scheduleMeasurements, 160);
  }, { passive: true });

  window.addEventListener("scroll", function () {
    if (scrollTimer) {
      return;
    }

    scrollTimer = window.setTimeout(function () {
      scrollTimer = 0;
      var offsets = getCurrentOffsets();
      updateStickyNavigationState(offsets.total);
      scheduleMeasurements();
    }, 60);
  }, { passive: true });

  if ("ResizeObserver" in window) {
    resizeObserver = new ResizeObserver(scheduleMeasurements);
    resizeObserver.observe(navShell);

    var adminBar = document.getElementById("wpadminbar");
    if (adminBar) {
      resizeObserver.observe(adminBar);
    }
  }

  if ("MutationObserver" in window && document.body) {
    mutationObserver = new MutationObserver(function (records) {
      var externalChange = records.some(function (record) {
        return !root.contains(record.target);
      });

      if (externalChange) {
        scheduleMeasurements();
      }
    });

    mutationObserver.observe(document.body, {
      attributes: true,
      attributeFilter: ["class", "style"],
      childList: true,
      subtree: true
    });
  }

  if (document.fonts && document.fonts.ready) {
    document.fonts.ready.then(scheduleMeasurements).catch(function () {
      return;
    });
  }

  scheduleMeasurements();

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", scheduleMeasurements, { once: true });
  }

  window.addEventListener("load", scheduleMeasurements, { once: true });
  window.setTimeout(scheduleMeasurements, 150);
  window.setTimeout(scheduleMeasurements, 500);
  window.setTimeout(scheduleMeasurements, 1200);

  if (window.location.hash) {
    window.setTimeout(function () {
      var target;
      try {
        target = root.querySelector(window.location.hash);
      } catch (error) {
        target = null;
      }
      if (target) {
        scrollToTarget(target, false);
      }
    }, 180);
  }

  var eligibilitySection = root.querySelector("#eligibility");
  if (eligibilitySection && eligibilitySection.getAttribute("data-kbc-eligibility-ready") !== "true") {
    eligibilitySection.setAttribute("data-kbc-eligibility-ready", "true");

    var eligibilityForm = eligibilitySection.querySelector("[data-kbc-eligibility-form]");
    var eligibilityGroups = eligibilityForm ? Array.prototype.slice.call(eligibilityForm.querySelectorAll("[data-question]")) : [];
    var indicationButton = eligibilityForm ? eligibilityForm.querySelector("[data-kbc-show-indication]") : null;
    var resultPanel = eligibilityForm ? eligibilityForm.querySelector("[data-kbc-eligibility-result]") : null;
    var resultTitle = resultPanel ? resultPanel.querySelector("[data-kbc-result-title]") : null;
    var resultText = resultPanel ? resultPanel.querySelector("[data-kbc-result-text]") : null;
    var resetCheckButton = resultPanel ? resultPanel.querySelector("[data-kbc-reset-check]") : null;
    var eligibilityAnswers = {};

    function setEligibilityAnswer(group, button) {
      var question = group.getAttribute("data-question");
      var buttons = Array.prototype.slice.call(group.querySelectorAll(".kbc-answer"));

      buttons.forEach(function (item) {
        var isSelected = item === button;
        item.setAttribute("aria-pressed", isSelected ? "true" : "false");
      });

      eligibilityAnswers[question] = button.getAttribute("data-value") || "";
    }

    eligibilityGroups.forEach(function (group) {
      Array.prototype.forEach.call(group.querySelectorAll(".kbc-answer"), function (button) {
        button.addEventListener("click", function () {
          setEligibilityAnswer(group, button);
        });
      });
    });

    if (indicationButton && resultPanel && resultTitle && resultText) {
      indicationButton.addEventListener("click", function () {
        var answered = eligibilityGroups.filter(function (group) {
          return Boolean(eligibilityAnswers[group.getAttribute("data-question")]);
        }).length;

        resultPanel.hidden = false;

        if (answered < eligibilityGroups.length) {
          resultTitle.textContent = "Complete the quick check";
          resultText.textContent = "Please answer all three questions to receive an initial indication.";
        } else {
          var values = Object.keys(eligibilityAnswers).map(function (key) {
            return eligibilityAnswers[key];
          });
          var allYes = values.every(function (value) {
            return value === "yes";
          });

          if (allYes) {
            resultTitle.textContent = "Your answers indicate potential suitability";
            resultText.textContent = "Your role and employer arrangements appear aligned with the pathway's initial requirements. KBC must still confirm role fit, prior learning, funding and the applicable start-date rules.";
          } else {
            resultTitle.textContent = "A suitability discussion is recommended";
            resultText.textContent = "One or more answers may need clarification. KBC can review your role, employer support and workplace opportunities before advising whether this pathway is appropriate.";
          }
        }

        resultPanel.focus({ preventScroll: true });
      });
    }

    if (resetCheckButton) {
      resetCheckButton.addEventListener("click", function () {
        eligibilityAnswers = {};
        eligibilityGroups.forEach(function (group) {
          Array.prototype.forEach.call(group.querySelectorAll(".kbc-answer"), function (button) {
            button.setAttribute("aria-pressed", "false");
          });
        });
        if (resultPanel) {
          resultPanel.hidden = true;
        }
        if (eligibilityGroups[0]) {
          var firstButton = eligibilityGroups[0].querySelector(".kbc-answer");
          if (firstButton) {
            firstButton.focus();
          }
        }
      });
    }
  }
}());
